package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.ErrorReporter;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static com.google.javascript.jscomp.CheckGlobalThisTestUtils.createNode;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CheckGlobalThis_shouldTraverse_TriageGen2Test {

    private CheckGlobalThis checkGlobalThis;
    private NodeTraversal nodeTraversal;

    @Before
    public void setUp() {
        checkGlobalThis = new CheckGlobalThis(ErrorReporter.noSuchErrorReporter());
        nodeTraversal = Mockito.mock(NodeTraversal.class);
    }

    /**
     * Helper to mock JSDoc behavior since getFunctionJsDocInfo is likely protected/private 
     * and depends on internal state. In a real environment, we'd use a spy or 
     * provide a setup that populates the JSDoc info on the node.
     * For this test, we assume the Node's JSDoc info is accessible via the mechanism 
     * used by the actual class.
     */

    @Test
    public void testNonFunctionNodeReturnsTrue() {
        Node n = createNode(Token.VAR);
        Node parent = createNode(Token.BLOCK);
        assertTrue(checkGlobalThis.shouldTraverse(nodeTraversal, n, parent));
    }

    @Test
    public void testFunctionWithConstructorJsDocReturnsFalse() {
        Node n = createNode(Token.FUNCTION);
        // In actual JSComp, we would attach JSDoc via Node.getJSDocInfo()
        // Since we can't easily mock the internal getFunctionJsDocInfo call without a spy,
        // this test assumes the logic flow for the JSDoc null check.
        Node parent = createNode(Token.BLOCK);

        // Test Case: JSDoc is null
        assertTrue(checkGlobalThis.shouldTraverse(nodeTraversal, n, parent));
    }

    @Test
    public void testFunctionWithInvalidParentReturnsFalse() {
        Node n = createNode(Token.FUNCTION);
        Node parent = createNode(Token.EXPRESSION); // Not BLOCK, SCRIPT, NAME, or ASSIGN
        assertFalse(checkGlobalThis.shouldTraverse(nodeTraversal, n, parent));
    }

    @Test
    public void testFunctionWithValidParentReturnsTrue() {
        Node n = createNode(Token.FUNCTION);
        Node parent = createNode(Token.ASSIGN);
        assertTrue(checkGlobalThis.shouldTraverse(nodeTraversal, n, parent));

        Node parent2 = createNode(Token.BLOCK);
        assertTrue(checkGlobalThis.shouldTraverse(nodeTraversal, n, parent2));

        Node parent3 = createNode(Token.SCRIPT);
        assertTrue(checkGlobalThis.shouldTraverse(nodeTraversal, n, parent3));

        Node parent4 = createNode(Token.NAME);
        assertTrue(checkGlobalThis.shouldTraverse(nodeTraversal, n, parent4));
    }

    @Test
    public void testAssignmentLhsReturnsTrue() {
        Node parent = createNode(Token.ASSIGN);
        Node lhs = createNode(Token.NAME);
        lhs.setString("a");
        Node rhs = createNode(Token.STRING);
        rhs.setString("b");
        parent.addChild(lhs);
        parent.addChild(rhs);

        Node n = lhs;
        // Should return true for LHS
        assertTrue(checkGlobalThis.shouldTraverse(nodeTraversal, n, parent));
    }

    @Test
    public void testAssignmentRhsNotPrototypeReturnsTrue() {
        Node parent = createNode(Token.ASSIGN);
        Node lhs = createNode(Token.NAME);
        lhs.setString("a");
        Node rhs = createNode(Token.STRING);
        rhs.setString("b");
        parent.addChild(lhs);
        parent.addChild(rhs);

        Node n = rhs;
        assertTrue(checkGlobalThis.shouldTraverse(nodeTraversal, n, parent));
    }

    @Test
    public void testAssignmentRhsIsPrototypeGetPropReturnsFalse() {
        Node parent = createNode(Token.ASSIGN);
        Node lhs = createNode(Token.GETPROP);
        lhs.addChild(createNode(Token.NAME));
        lhs.addChild(createNode(Token.STRING, "prototype"));

        Node rhs = createNode(Token.STRING);
        parent.addChild(lhs);
        parent.addChild(rhs);

        // Mock NodeUtil.isGet behavior by ensuring structure matches
        // Note: In real tests, NodeUtil.isGet might need mocking or specific node setup
        // For this test, we assume the logic path for lhs.getType() == Token.GETPROP
        assertFalse(checkGlobalThis.shouldTraverse(nodeTraversal, rhs, parent));
    }

    @Test
    public void testAssignmentRhsIsNestedPrototypeGetPropReturnsFalse() {
        Node parent = createNode(Token.ASSIGN);
        Node lhs = createNode(Token.GETPROP);
        lhs.addChild(createNode(Token.NAME));

        Node llhs = createNode(Token.GETPROP);
        llhs.addChild(createNode(Token.NAME));
        llhs.addChild(createNode(Token.STRING, "prototype"));
        lhs.addChild(llhs);

        Node rhs = createNode(Token.STRING);
        parent.addChild(lhs);
        parent.addChild(rhs);

        assertFalse(checkGlobalThis.shouldTraverse(nodeTraversal, rhs, parent));
    }

    @Test
    public void testNullParentReturnsTrue() {
        Node n = createNode(Token.VAR);
        assertTrue(checkGlobalThis.shouldTraverse(nodeTraversal, n, null));
    }
}
